guided.solution:
def to_number(text):
    text = text.strip()
    if text in ("-", "n/a"):
        return None
    negative = text.startswith("(") and text.endswith(")")
    cleaned = text.strip("()").replace("$", "").replace(",", "")
    value = float(cleaned)
    return -value if negative else value

for t in ["$1,250.50", "(300.00)", " 99 ", "-"]:
    print(to_number(t))
